import java.util.Scanner;
public class JRepeatedSequence1 {
	public static void main(String[] args){
		//Khatwa 1: Qiraat al adad al sahih N alladhi yadkhilhu al mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil al-adad al-sahi N: ");
		int N = scan.nextInt();
		scan.close();
		//Khatwa 2: Tiba'at N a'adad mafsoola bimasaafa
		for (int i = 1; i <= N; i++) {
			//Khatwa 2.1: Tiba'at al raqam i khams marrat
		    for (int j = 1; j <= 5; j++) {
		        System.out.print(i);    
		    } 
		    System.out.print(" ");
		}
	}
}
